"use client";
// Screen 17 — First Diagnosis. The "wow" moment: an intelligence surface, not a dashboard.
// For user workspaces the diagnosis is GENERATED by the AI from the owner's own
// checkup answers (POST /api/checkup/diagnosis). "Improve my diagnosis" replaces
// it with a refined version computed from the channel numbers the owner entered.
// The template content below is only the fallback when no checkup facts exist.

import React, { useEffect, useRef, useState } from "react";
import { ArrowRight, Eye, Loader2, Search, Sparkles, TrendingDown } from "lucide-react";
import { Button } from "@/components/ui/button";
import { InfoBanner } from "@/components/shared/layout";
import { ProvenanceBadge, TrendBadge } from "@/components/shared/badges";
import { useBizz } from "@/lib/store";
import type { DiagnosisContent } from "@/lib/checkup";
import type { Goodness } from "@/lib/types";
import type { ScreenProps } from "../view-types";

const TEMPLATE_DELTAS: DiagnosisContent["deltas"] = [
  { label: "Marketing spend", delta: 40, goodness: "neutral", caption: "You invested more in ads" },
  { label: "Enquiries", delta: 50, goodness: "good", caption: "Demand responded" },
  { label: "Customers", delta: 4, goodness: "neutral", caption: "Barely moved" },
  { label: "Revenue", delta: 3, goodness: "neutral", caption: "Barely moved" },
];

const TEMPLATE: DiagnosisContent = {
  headline: "We found the first thing worth investigating.",
  story:
    "Your marketing activity and enquiries increased much faster than your number of customers. Your immediate constraint may be conversion rather than lead generation.",
  deltas: TEMPLATE_DELTAS,
  meaning:
    "Demand is not the problem. Enquiries grew roughly 12 times faster than customers did. The drop-off is most likely happening after the enquiry arrives — in response time, quoting, or follow-up — rather than in how many people discover you.",
  whyItMatters:
    "If customer conversion had kept pace with enquiries, the same ad spend could have produced close to twice as many new customers. Spending more on marketing before fixing conversion would amplify the gap — and the waste.",
  nextInvestigation:
    "Compare how each channel converts enquiries into customers, and check how quickly enquiries receive a first response. Your Instagram enquiries grew the fastest, yet converted far worse than referrals — that contrast is the fastest route to the real constraint.",
  confidence: 62,
};

export default function FirstDiagnosis(_props: ScreenProps) {
  const navigate = useBizz((s) => s.navigate);
  const facts = useBizz((s) => s.checkup.facts);
  const storedDiagnosis = useBizz((s) => s.checkup.diagnosis);
  const improved = useBizz((s) => s.checkup.improved);
  const userWorkspace = useBizz((s) => s.userWorkspace);
  const setCheckupDiagnosis = useBizz((s) => s.setCheckupDiagnosis);

  const [generating, setGenerating] = useState(false);
  const requested = useRef(false);

  // Generate the personalized diagnosis once, when facts exist but none is stored yet.
  useEffect(() => {
    if (!facts || storedDiagnosis || improved || requested.current) return;
    requested.current = true;
    setGenerating(true);
    void (async () => {
      try {
        const res = await fetch("/api/checkup/diagnosis", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            workspaceName: userWorkspace?.name ?? "Your business",
            country: userWorkspace?.country ?? "Nigeria",
            currency: userWorkspace?.currency ?? "₦",
            facts,
          }),
        });
        const data = (await res.json()) as { ok?: boolean; diagnosis?: DiagnosisContent };
        if (data?.ok && data.diagnosis) setCheckupDiagnosis(data.diagnosis);
      } catch {
        // Silent — the template fallback is already rendered.
      } finally {
        setGenerating(false);
      }
    })();
  }, [facts, storedDiagnosis, improved, userWorkspace, setCheckupDiagnosis]);

  const isPersonalized = Boolean(facts);
  const content: DiagnosisContent = improved
    ? {
        headline: improved.headline,
        story: improved.story,
        deltas: [
          { label: "Marketing spend", delta: 0, goodness: "neutral", caption: "Measured counts entered" },
          ...improved.channelRows.slice(0, 3).map((r) => ({
            label: r.name,
            delta: 0,
            goodness: (r.name === improved.worstChannel ? "bad" : "good") as Goodness,
            caption: `${r.customers}/${r.enquiries} enquiries — ${r.conversion.toFixed(1)}%`,
          })),
        ],
        meaning: improved.meaning,
        whyItMatters: improved.whyItMatters,
        nextInvestigation: improved.nextInvestigation,
        confidence: improved.confidence,
      }
    : storedDiagnosis ?? TEMPLATE;

  return (
    <div className="mx-auto w-full max-w-3xl">
      {improved ? (
        <div className="mb-6">
          <InfoBanner tone="success" title={`Diagnosis improved — confidence increased to ${improved.confidence}%`}>
            {improved.bestChannel !== improved.worstChannel
              ? `${improved.worstChannel} converts at ${
                  improved.channelRows.find((r) => r.name === improved.worstChannel)?.conversion.toFixed(1) ?? "—"
                }% vs ${improved.channelRows.find((r) => r.name === improved.bestChannel)?.conversion.toFixed(1) ?? "—"}% for ${improved.bestChannel}. The investigation now has a measured target.`
              : "Channel counts are now part of your diagnosis."}
          </InfoBanner>
        </div>
      ) : null}

      {/* Hero intelligence surface */}
      <section
        aria-label="Your first diagnosis"
        className="relative overflow-hidden rounded-2xl border border-violet-200 bg-violet-50/60 p-6 sm:p-10"
      >
        <div
          aria-hidden
          className="pointer-events-none absolute -right-24 -top-24 size-72 rounded-full bg-violet-200/40 blur-3xl"
        />
        <div
          aria-hidden
          className="pointer-events-none absolute -bottom-28 -left-20 size-72 rounded-full bg-violet-100/60 blur-3xl"
        />

        <div className="relative">
          <p className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wide text-violet-700">
            <Sparkles className="size-4" aria-hidden />
            Your first diagnosis
          </p>
          <h1 className="mt-3 max-w-xl text-3xl font-bold tracking-tight sm:text-4xl">
            {content.headline}
          </h1>
          <blockquote className="mt-5 max-w-2xl border-l-2 border-violet-400 pl-4 text-base leading-relaxed text-slate-700 sm:text-lg">
            {content.story}
          </blockquote>
          <p className="mt-3 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            <ProvenanceBadge provenance="ai-interpretation" />
            {isPersonalized
              ? "Generated from the trends you described in your checkup — not from measured channel data yet."
              : "Based on the trends you described — not on measured channel data yet."}
          </p>

          {/* Delta story */}
          <div className="mt-8 grid grid-cols-2 gap-3 sm:gap-4 md:grid-cols-4">
            {content.deltas.map((d) => (
              <div key={d.label} className="rounded-xl border border-violet-100 bg-white/80 p-4">
                <p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">{d.label}</p>
                <p className="mt-1.5 text-2xl font-semibold tnum text-slate-900 sm:text-3xl">
                  {d.delta > 0 ? "+" : ""}
                  {d.delta}%
                </p>
                <TrendBadge delta={d.delta} goodness={d.goodness} className="mt-2" />
                <p className="mt-2 text-xs text-muted-foreground">{d.caption}</p>
              </div>
            ))}
          </div>
          <p className="mt-3 text-xs text-muted-foreground">
            {improved
              ? "Channel conversion is now measured from the counts you entered."
              : "Your last full month vs the month before, as you described it."}
          </p>
        </div>
      </section>

      {generating ? (
        <p className="mt-6 flex items-center gap-2 rounded-xl border border-violet-100 bg-violet-50/60 px-4 py-3 text-sm text-violet-800" role="status">
          <Loader2 className="size-4 animate-spin" aria-hidden />
          Writing your personalized diagnosis from your checkup answers…
        </p>
      ) : null}

      {/* Reading of the result */}
      <section className="mt-8 space-y-6" aria-label="Interpretation">
        <div>
          <h2 className="flex items-center gap-2 text-sm font-semibold">
            <Search className="size-4 text-violet-600" aria-hidden />
            What this means
          </h2>
          <p className="mt-1.5 text-sm leading-relaxed text-slate-700">{content.meaning}</p>
        </div>

        <div>
          <h2 className="flex items-center gap-2 text-sm font-semibold">
            <TrendingDown className="size-4 text-amber-600" aria-hidden />
            Why it matters
          </h2>
          <p className="mt-1.5 text-sm leading-relaxed text-slate-700">{content.whyItMatters}</p>
        </div>

        <div className="rounded-xl border border-violet-200 bg-violet-50/60 p-4 sm:p-5">
          <h2 className="flex items-center gap-2 text-sm font-semibold text-violet-800">
            <Sparkles className="size-4" aria-hidden />
            Recommended next investigation
          </h2>
          <p className="mt-1.5 text-sm leading-relaxed text-violet-900/90">{content.nextInvestigation}</p>
        </div>
      </section>

      <div className="mt-8 flex flex-col gap-2 sm:flex-row">
        <Button onClick={() => navigate("first-diagnosis-evidence")} className="w-full bg-violet-600 hover:bg-violet-700 sm:w-auto">
          <Eye className="size-4" aria-hidden />
          See the evidence
        </Button>
        <Button variant="outline" className="w-full sm:w-auto" onClick={() => navigate("improve-diagnosis")}>
          Improve this diagnosis
          <ArrowRight className="size-4" aria-hidden />
        </Button>
      </div>
    </div>
  );
}
